@c1 syntax.clause form=imperative verb="repaet" modifier="again" complement=$n1
@n1 syntax.nominal dependent="the" head="reversal"
@r1 syntax.relation attachment=ambiguous marker="from" from=$c1 to=$n2
@n2 syntax.nominal dependent="the" dependent="other" head="end"

@c1 syntax.clause form=imperative verb="do" complement=$n1
@n1 syntax.nominal dependent="the" dependent="same" head="ladder"
@r1 syntax.relation marker="on" from=$n1 to=$n2
@n2 syntax.nominal dependent="the" dependent="next" head="row"

@n1 syntax.nominal dependent="same" dependent="backwards" head="ladder"
@r1 syntax.relation marker="on" from=$n1 to=$n2
@n2 syntax.nominal dependent="the" head="row"
@c1 syntax.clause form=fragment modifier="below" complement=$n1
